CREATE PROCEDURE thcdnaproddata.daac_ods.sp_ing_conversion_thc_src_update(OUT OUT_PARAM INT64)
BEGIN

/* --------------------------------------------------------------------------------------------------------------- */
-- Proc name : sp_ing_conversion_thc_src_update
-- Database: Staging
-- Author : Shashank Madishetti
-- Project: Staging 
-- Proc Desc : Stored procedure to update facility code thc src column in HIST tables based on conversion in bundle detail entry.
-- 
-- Parameters: None
--
-- Revision History:
-- When Version Modified by Change description
-- --------------------------------------------------------------------------------------------------
-- 20250805 1.0 Shashank Madishetti Created!
/* --------------------------------------------------------------------------------------------------------------- */

DECLARE V_UPDATE_COUNT INT64;
DECLARE V_PROC_NAME STRING;
DECLARE V_SQL STRING;
DECLARE V_LOG_MESSAGE STRING;

BEGIN
--SET SERIALIZABLE = FALSE;
SET V_PROC_NAME = 'sp_ing_conversion_thc_src_update';
SET V_LOG_MESSAGE = 'Starting Procedure - ' || V_PROC_NAME || ' - ' || FORMAT_DATETIME('%Y%m%d %H:%M:%E*S',CURRENT_DATETIME("America/Chicago") );
SELECT  V_LOG_MESSAGE;

-- taking backup of hosp_src column to hosp_thc_src column 
update daac_ods.daac_bill_hist set B1HOSP_thc_src = B1HOSP_src where lower(trim(B1HOSP)) != lower(trim(B1HOSP_src)) and B1HOSP_thc_src is null;
update daac_ods.daac_demog_hist set v3hosp_thc_src = v3hosp_src where lower(trim(v3hosp)) != lower(trim(v3hosp_src)) and v3hosp_thc_src is null;
update daac_ods.daac_finsumnew_hist set f2hosp_thc_src = f2hosp_src where lower(trim(f2hosp)) != lower(trim(f2hosp_src)) and f2hosp_thc_src is null;
update daac_ods.non_pbar_bill_hist set B1HOSP_thc_src = B1HOSP_src where lower(trim(B1HOSP)) != lower(trim(B1HOSP_src)) and B1HOSP_thc_src is null;
update daac_ods.non_pbar_demog_hist set V3HOSP_thc_src = V3HOSP_src where lower(trim(V3HOSP)) != lower(trim(V3HOSP_src)) and V3HOSP_thc_src is null;
update daac_ods.non_pbar_finsumnew_hist set F2HOSP_thc_src = F2HOSP_src where lower(trim(F2HOSP)) != lower(trim(F2HOSP_src)) and F2HOSP_thc_src is null;
update daac_ods.non_pbar_icd10proc_hist set I10PHOSP_thc_src = I10PHOSP_src where lower(trim(I10PHOSP)) != lower(trim(I10PHOSP_src)) and I10PHOSP_thc_src is null;
update daac_ods.non_pbar_mdtable_all_hist set T1HOSP_thc_src = T1HOSP_src where lower(trim(T1HOSP)) != lower(trim(T1HOSP_src)) and T1HOSP_thc_src is null;
update daac_ods.non_pbar_patdrg_hist set PDHOSP_thc_src = PDHOSP_src where lower(trim(PDHOSP)) != lower(trim(PDHOSP_src)) and PDHOSP_thc_src is null;
update daac_ods.non_pbar_patins_hist set F1HOSP_thc_src = F1HOSP_src where lower(trim(F1HOSP)) != lower(trim(F1HOSP_src)) and F1HOSP_thc_src is null;
update daac_ods.non_pbar_patmds_hist set TCHOSP_thc_src = TCHOSP_src where lower(trim(TCHOSP)) != lower(trim(TCHOSP_src)) and TCHOSP_thc_src is null;
-- START OPTIMIZED QUERY
MERGE `daac_ods.non_pbar_patphys_hist` AS T
USING (
  -- This subquery identifies the primary keys of all rows that need to be updated.
  SELECT
    non_pbar_patphys_hk
  FROM
    `daac_ods.non_pbar_patphys_hist`
  WHERE
    lower(trim(M4HOSP)) != lower(trim(M4HOSP_src))
    AND M4HOSP_thc_src IS NULL
) AS S
ON T.non_pbar_patphys_hk = S.non_pbar_patphys_hk
WHEN MATCHED THEN
  -- For the matched rows, update M4HOSP_thc_src with the value from the row's own M4HOSP_src column.
  UPDATE SET T.M4HOSP_thc_src = T.M4HOSP_src;
-- END OPTIMIZED QUERY;
update daac_ods.non_pbar_srg9desc_hist set Z52HOSP_thc_src = Z52HOSP_src where lower(trim(Z52HOSP)) != lower(trim(Z52HOSP_src)) and Z52HOSP_thc_src is null;
update daac_ods.non_pbar_visit_hist set V7HOSP_thc_src = V7HOSP_src where lower(trim(V7HOSP)) != lower(trim(V7HOSP_src)) and V7HOSP_thc_src is null;
update daac_ods.statfile_intg set STHOSP_thc_src = STHOSP_src where lower(trim(STHOSP)) != lower(trim(STHOSP_src)) and STHOSP_thc_src is null;
update daac_ods.non_pbar_ancdstfile_hist set ANCHOSP_thc_src = ANCHOSP_src where lower(trim(ANCHOSP)) != lower(trim(ANCHOSP_src)) and ANCHOSP_thc_src is null;

-- setting non_pbar_admit_src_thc_src_hk for non_pbar_visit_hist
UPDATE daac_ods.non_pbar_visit_hist SET non_pbar_admit_src_thc_src_hk = non_pbar_admit_src_src_hk WHERE v7hosp_thc_src is not null and non_pbar_admit_src_thc_src_hk is null;

--V_UPDATE_COUNT := ROW_COUNT;
SELECT 'All updates completed.';

    SET OUT_PARAM = 1;
    SELECT OUT_PARAM;
RETURN ;

-- EXCEPTION 
-- WHEN ERROR THEN

-- SET V_LOG_MESSAGE = 'FAILED - Procedure ' || V_PROC_NAME || ', Reason: TRANSACTION_ABORTED - ' || REPLACE(@@error.message,'\'\'','\'\'\'\'');
-- select V_LOG_MESSAGE;
--         SET OUT_PARAM = 0;
--         SELECT OUT_PARAM;
-- RETURN ;

EXCEPTION
WHEN ERROR THEN 

SET V_LOG_MESSAGE = 'FAILED - Procedure ' || V_PROC_NAME || ', ' || REPLACE(@@error.message,'\'\'','\'\'\'\'');
select V_LOG_MESSAGE;
        SET OUT_PARAM = 0;
        SELECT OUT_PARAM; 
-- RETURN ;
 RAISE USING message = FORMAT("Hey, you. When you executed %s at %s, it caused an error: %s. Please don't do that.", @@error.statement_text, @@error.formatted_stack_trace, @@error.message);

END;
END;

