-- START OPTIMIZED QUERY
MERGE `daac_ods.daac_patphys_hist` AS T
USING (
  -- De-duplicate the source to ensure deterministic updates and prevent MERGE errors.
  -- The original UPDATE...FROM was non-deterministic; ROW_NUMBER() without ORDER BY mimics this.
  SELECT
    from_facility_cd,
    to_facility_cd
  FROM `staging.stg_facility_conversion`
  QUALIFY ROW_NUMBER() OVER(PARTITION BY from_facility_cd) = 1
) AS S
ON TRIM(T.m4hosp, ' ') = S.from_facility_cd
WHEN MATCHED THEN
  UPDATE SET T.m4hosp = S.to_facility_cd;
-- END OPTIMIZED QUERY;

