-- RETURN ;



EXCEPTION
WHEN ERROR THEN 

SET V_LOG_MESSAGE = 'FAILED - Procedure ' || V_PROC_NAME || ', ' || REPLACE(@@error.message,'/'/'','/'/'/'/'');
SELECT V_LOG_MESSAGE;
SET OUT_PARAM = 0;
-- RETURN ;
 RAISE USING message = FORMAT("Hey, you. When you executed %s at %s, it caused an error: %s. Please don't do that.", @@error.statement_text, @@error.formatted_stack_trace, @@error.message);
END;
END;

CREATE PROCEDURE thcdnaproddata.daac_ods.sp_stg_process_hist_facility_conversion_pbar(OUT OUT_PARAM INT64)
BEGIN
/* --------------------------------------------------------------------------------------------------------------- */
-- Proc name : SP_STG_PROCESS_HIST_FACILITY_CONVERSION_PBAR
-- Author : Aditya Devarasetty
-- Dataset: daac_ods 
-- Proc Desc : Stored procedure to convert and update Facility code in PBAR HIST tables based on STG_FACILITY_CONVERSION.
-- 
-- Parameters: None
--
-- Revision History:
-- When Version Modified by Change description
