-- START OPTIMIZED QUERY
/*
NOTE: This rewrite to MERGE is contingent on the existence of a unique key
(or a composite of columns that uniquely identifies each row) in the table,
represented here as `__row_identifier__`. If no such key exists,
this rewrite is not possible, and schema-level optimizations are required.
*/
MERGE daac_ods.daac_charges_hist AS T
USING (
  -- Subquery to efficiently identify only the rows that need to be changed
  SELECT
    __row_identifier__, -- IMPORTANT: Replace with the actual primary key column(s)
    v2hosp_src
  FROM
    daac_ods.daac_charges_hist
  WHERE
    LOWER(TRIM(v2hosp)) != LOWER(TRIM(v2hosp_src))
    AND v2hosp_thc_src IS NULL
) AS S
ON
  T.__row_identifier__ = S.__row_identifier__ -- Join condition using the primary key
WHEN MATCHED THEN
  UPDATE
  SET
    T.v2hosp_thc_src = S.v2hosp_src;
-- END OPTIMIZED QUERY;
