 The performance gains will come from implementing the data hygiene recommendations.
*/
MERGE daac_ods.daac_charges_hist AS T
USING staging.stg_facility_conversion AS S
  ON TRIM(T.v2hosp, ' ') = S.from_facility_cd
WHEN MATCHED THEN
  UPDATE SET v2hosp = S.to_facility_cd;
-- END OPTIMIZED QUERY;
