CREATE PROCEDURE thcdnadevdata.dmor.sp_er_provider_consult_opti(OUT OUT_PARAM INT64)
BEGIN


DECLARE	V_PROC_NAME STRING(255);
DECLARE	V_LOG_MESSAGE STRING(4000);
DECLARE SERIALIZABLE BOOLEAN;

/*

20181116  	1.0  -- Tamil U		-- Initial Version
20181207	1.1	 -- Tamil U		-- Removed the filter to Physician Consults and added event codes from table  INTERNAL.REF_ER_CONSULT_EVENT_CODES instead


*/
BEGIN
	/* Set Serializable to False to avoid Failures during parallel runs */
	SET SERIALIZABLE = FALSE;

	/* Start Procedure */
	SET V_PROC_NAME = 'sp_er_provider_consult';				
	SET V_LOG_MESSAGE = 'Starting Procedure - ' || V_PROC_NAME || ' - ' || CURRENT_DATETIME("America/Chicago");
	SELECT '%', V_LOG_MESSAGE;		

	EXECUTE IMMEDIATE 'TRUNCATE TABLE thcdnadevdata.dmor.er_provider_consult';
	SELECT 'Table Truncated... ER_PROVIDER_CONSULT... : %';

    SELECT 'TEMP Table creation started...: %';

	CREATE TEMP TABLE TEMP_ER_PAN AS
	select DISTINCT 
		substr(cv.display,1,3) as FACILITY_CD
		, encntr_alias2.alias PATIENT_ACCOUNT_NBR
		--, encntr_alias.alias mrn 
		, encounter.encntr_id
        , encounter.HEALTH_SYSTEM_SOURCE_ID
	From thcdnadevdata.cerner_ods.cerner_encounter_hist encounter 
	inner join thcdnadevdata.cerner_ods.cerner_encntr_alias_hist encntr_alias 
		on ( encounter.HEALTH_SYSTEM_SOURCE_ID = encntr_alias.HEALTH_SYSTEM_SOURCE_ID 
			and encounter.ENCNTR_ID = encntr_alias.ENCNTR_ID
						and encntr_alias.ENCNTR_ALIAS_TYPE_CD = 1079 )
	inner join thcdnadevdata.cerner_ods.cerner_encntr_alias_hist encntr_alias2 
		on ( encounter.HEALTH_SYSTEM_SOURCE_ID = encntr_alias2.HEALTH_SYSTEM_SOURCE_ID 
			and encounter.ENCNTR_ID = encntr_alias2.ENCNTR_ID
						and encntr_alias2.ENCNTR_ALIAS_TYPE_CD = 1077 )
	inner join thcdnadevdata.cerner_ods.cerner_encntr_loc_hist_hist loc 
		ON ( encounter.ENCNTR_ID = loc.ENCNTR_ID 
			and encounter.HEALTH_SYSTEM_SOURCE_ID = loc.HEALTH_SYSTEM_SOURCE_ID )
	inner join thcdnadevdata.cerner_ods.cerner_code_value_hist cv 
		on ( encounter.LOC_FACILITY_CD = cv.CODE_VALUE 
			and encounter.HEALTH_SYSTEM_SOURCE_ID = cv.HEALTH_SYSTEM_SOURCE_ID )
	where loc.ENCNTR_TYPE_CD in (309310) -- in (309308,309309,309310) -- respectively 'Inpatient','Outpatient','Emergency'
			--and encounter.ENCNTR_ID in ('56646582') 
	;
	SELECT 'TEMP TABLE  CREATED with row count: %', @@row_count;

	SET V_LOG_MESSAGE = 'Temp table created time - ' || CURRENT_DATETIME("America/Chicago");
	SELECT '%', V_LOG_MESSAGE;		

-- CONVERT_TIMEZONE(ORIG_ORDER_DT_TM, DST_FLAG, FAC_TZ) AS ORDER_DT_TM,

BEGIN;

 -- START OPTIMIZED QUERY
INSERT INTO thcdnadevdata.dmor.er_provider_consult (
  FACILITY_CD,
  PATIENT_ACCOUNT_NBR,
  encntr_id,
  ORDER_ID,
  ORDER_MNEMONIC,
  ORIG_ORDER_DT_TM,
  EVENT_END_DT_TM,
  EVENT_CD,
  EVENT_DISPLAY,
  RESULT_VAL,
  RESULT_DT_TM
)
WITH
  FilteredOrders AS (
    SELECT
      ORD.HEALTH_SYSTEM_SOURCE_ID,
      ORD.order_id,
      ORD.order_mnemonic,
      ORD.orig_order_dt_tm,
      ORD.encntr_id
    FROM
      thcdnadevdata.cerner_ods.cerner_orders_hist AS ORD
    WHERE
      UPPER(ORD.ORDER_MNEMONIC) IN (
        'CASE MANAGEMENT CONSULT',
        'CONSULT TO CASE MANAGEMENT',
        'MEDICAL SERVICE CONSULT',
        'PHYSICIAN/PROVIDER CONSULT',
        'PHYSICIAN/PROVIDER CONSULTS'
      )
      AND ORD.ORIG_ORDER_DT_TM >= DATETIME(
        LEAST(
          DATE_TRUNC(CURRENT_DATE("America/Chicago"), YEAR),
          DATE_SUB(
            DATE_TRUNC(CURRENT_DATE("America/Chicago"), MONTH),
            INTERVAL 6 MONTH
          )
        )
      )
  ),
  EnrichedEvents AS (
    SELECT DISTINCT
      C.encntr_id,
      ORD.order_id,
      ORD.order_mnemonic,
      ORD.orig_order_dt_tm,
      C.EVENT_END_DT_TM,
      C.EVENT_CD,
      CC.DISPLAY AS EVENT_DISPLAY,
      C.RESULT_VAL,
      R.RESULT_DT_TM,
      ORD.HEALTH_SYSTEM_SOURCE_ID
    FROM
      FilteredOrders AS ORD
      INNER JOIN thcdnadevdata.cerner_ods.cerner_clinical_event_hist AS C
        ON ORD.order_id = C.order_id
        AND ORD.HEALTH_SYSTEM_SOURCE_ID = C.HEALTH_SYSTEM_SOURCE_ID
      INNER JOIN thcdnadevdata.dmor.ref_er_consult_event_codes AS EC
        ON C.EVENT_CD = EC.EVENT_CD
      INNER JOIN thcdnadevdata.cerner_ods.cerner_code_value_hist AS CC
        ON CC.CODE_VALUE = C.EVENT_CD
        AND CC.HEALTH_SYSTEM_SOURCE_ID = C.HEALTH_SYSTEM_SOURCE_ID
      LEFT JOIN thcdnadevdata.cerner_ods.cerner_ce_date_result_hist AS R
        ON R.EVENT_ID = C.EVENT_ID
        AND R.HEALTH_SYSTEM_SOURCE_ID = C.HEALTH_SYSTEM_SOURCE_ID
  )
SELECT
  ENC.FACILITY_CD,
  ENC.PATIENT_ACCOUNT_NBR,
  ORD.encntr_id,
  ORD.ORDER_ID,
  ORD.ORDER_MNEMONIC,
  staging.convert_timezone(ORD.ORIG_ORDER_DT_TM, DF.DST_FLAG, DF.FAC_TZ) AS ORIG_ORDER_DT_TM,
  staging.convert_timezone(ORD.EVENT_END_DT_TM, DF.DST_FLAG, DF.FAC_TZ) AS EVENT_END_DT_TM,
  ORD.EVENT_CD,
  ORD.EVENT_DISPLAY,
  ORD.RESULT_VAL,
  staging.convert_timezone(ORD.RESULT_DT_TM, DF.DST_FLAG, DF.FAC_TZ) AS RESULT_DT_TM
FROM
  TEMP_ER_PAN AS ENC
  INNER JOIN EnrichedEvents AS ORD
    ON ENC.encntr_id = ORD.encntr_id
    AND ENC.HEALTH_SYSTEM_SOURCE_ID = ORD.HEALTH_SYSTEM_SOURCE_ID
  INNER JOIN thcdnadevdata.dmor.dim_fac AS DF
    ON ENC.FACILITY_CD = DF.FACILITY_CD;
-- END OPTIMIZED QUERY

  COMMIT;

	SELECT 'INTERNAL.ER_PROVIDER_CONSULT TABLE INSERTED with row count: %', @@row_count;

	SET V_LOG_MESSAGE = 'Insert INTERNAL.ER_PROVIDER_CONSULT Completed time - ' || CURRENT_DATETIME("America/Chicago");
	SELECT '%', V_LOG_MESSAGE;	

  SET OUT_PARAM = 1;
  SELECT OUT_PARAM;
  RETURN;	

	--CREATE OR REPLACE VIEW V_ER_PROVIDER_CONSULT AS SELECT * FROM INTERNAL.ER_PROVIDER_CONSULT;
	--RAISE NOTICE 'VIEW RECREATED , INTERNAL.ER_PROVIDER_CONSULT : %', ROW_COUNT;

/* =============================================================================================================================== */
/* HANDLE EXCEPTIONS 
/* =============================================================================================================================== */
EXCEPTION 
	WHEN ERROR THEN
		ROLLBACK;
		SET V_LOG_MESSAGE = 'FAILED - Procedure ' || V_PROC_NAME || ', Reason: TRANSACTION_ABORTED - ' || REPLACE(@@error.message,'\'','\'\'');
		SELECT '%', V_LOG_MESSAGE;

    SET V_LOG_MESSAGE = 'FAILED - Procedure ' || V_PROC_NAME || ', ' || REPLACE(@@error.message,'\'','\'\'');
		SELECT '%', V_LOG_MESSAGE;

    SET OUT_PARAM = 0;
    SELECT OUT_PARAM;
		--RETURN;


RAISE USING message = FORMAT("Hey, you. On Execution of %s at %s, it caused an error: %s.", @@error.statement_text, @@error.formatted_stack_trace, @@error.message);
END;
END;

CREATE OR REPLACE PROCEDURE `thcdnadevdata.idm.sp_cnl_dim_order_opti`(IN IN_PARAM DATE, OUT OUT_PARAM INT64)
BEGIN
/*
Purpose
-XXX
Details
-XXX
Target
-DIM_ORDER
Dependencies
IDM.BASE_ENCOUNTER_CLINICAL
cerner_ods.cerner_orders_hist
cerner_ods.cerner_order_catalog_hist
cerner_ods.cerner_order_catalog_synonym_hist
cerner_ods.cerner_code_value_hist
cerner_ods.cerner_code_value_hist
cerner_ods.dmc_orders_hist
cerner_ods.dmc_order_catalog_hist
cerner_ods.dmc_order_catalog_synonym_hist
cerner_ods.dmc_code_value_hist
cerner_ods.dmc_code_value_hist
Assumptions
-XXX

Notes
-XXX

Revision History
--20180912 - 1.0 - Ashish Mishra - Initial version
--20181113 - 1.1 - Ashish Mishra - Phase-2(Add MULTUM CODE column)
--20181119 - 1.2 - Ashish Mishra - Fix prod issue for cki filter
--20190518 20:43:00 - 2.1 - Richard Chiang - adding delta logic for the dimension and replace sequence with row_number() and add execute_sql and update proc name
--20190521 12:10:00 - 2.2 - Richard Chiang - remove idm references and update unique id to favor new record
--20190522 12:30:00 - 2.3 - Richard Chiang - reinstate references and change sequence to max and update to favor old record
*/


	DECLARE I_PROCESS_DT STRING  ;
	DECLARE V_PROCESS_DT STRING;
	DECLARE V_LOG_TABLE STRING;
	DECLARE V_START_TS DATETIME;
	DECLARE V_END_TS DATETIME;
	DECLARE V_START_TS_TEXT STRING;
	DECLARE V_END_TS_TEXT STRING;
	DECLARE V_PROC_NAME STRING;
	DECLARE V_RAND_NBR INT64;
	DECLARE V_ERROR_MESSAGE STRING;
	DECLARE V_SQL_START_TS DATETIME;
	DECLARE V_SQL_END_TS DATETIME;
	DECLARE V_ROW_COUNT INT64;
	DECLARE V_SQL_START_TS_TEXT STRING;
	DECLARE V_SQL_END_TS_TEXT STRING;
	DECLARE V_SQL_LOG STRING;
	DECLARE V_LOG_TS_TEXT STRING;
	DECLARE V_RESULT STRING;
	DECLARE V_PAREMETER_LIST STRING;
	DECLARE V_CNT INT64;
	DECLARE V_DIM_ORDER_SK_MAX INT64;

BEGIN
SET I_PROCESS_DT = FORMAT_DATE('%Y-%m-%d',IN_PARAM);
SET V_START_TS = CURRENT_DATETIME("America/Chicago");
SELECT 'Procedure Starting.';
SET V_START_TS_TEXT = FORMAT_DATETIME('%Y%m%d %H:%M:%E*S',V_START_TS);
SET V_LOG_TS_TEXT = FORMAT_DATETIME('%Y%m%d%H%M%S',V_START_TS);
SET V_PROC_NAME = 'sp_cnl_dim_order';
SET V_RAND_NBR = CAST(RAND()*pow(10,15) AS BIGINT);
SET V_PROCESS_DT = I_PROCESS_DT;
SELECT 'V_PROCESS_DT:', V_PROCESS_DT;
SET V_LOG_TABLE = 'TEMP_LOG_'||V_LOG_TS_TEXT||'_'||V_RAND_NBR;
SELECT 'V_PROCESS_DT:', V_LOG_TABLE;
--pipe separated list of parameters
SET V_PAREMETER_LIST = V_PROCESS_DT;

execute immediate 'create temporary table '||V_LOG_TABLE||' as select * from thcdnadevdata.idm.sp_log where 1 = 2';
SELECT 'V_PROCESS_DT: ', V_PROC_NAME;
SELECT 'V_PROCESS_DT: ', V_LOG_TABLE;


--********************************TRUNCATE and reset sequence START***************************************************************
--reset sequence
SET V_DIM_ORDER_SK_MAX = (SELECT IFNULL(MAX(DIM_ORDER_SK),0) from thcdnadevdata.idm.dim_order);

--Drop temp table cerner
DROP TABLE IF EXISTS thcdnadevdata.idm.cerner_ord_encntr;

--Drop temp table dmc
DROP TABLE IF EXISTS thcdnadevdata.idm.dmc_ord_encntr;


--********************************TRUNCATE and reset sequence END*****************************************************************

CALL `thcdnadevdata.idm.execute_sql`('CREATE TABLE IF NOT EXISTS thcdnadevdata.idm.cerner_ord_encntr AS SELECT DISTINCT ORD_HIST.CATALOG_TYPE_CD,ORD_HIST.DCP_CLIN_CAT_CD,ORD_HIST.SYNONYM_ID,ORD_HIST.CATALOG_CD, ORD_HIST.HEALTH_SYSTEM_SOURCE_ID,regexp_replace(regexp_replace(ORD_HIST.ORDER_DETAIL_DISPLAY_LINE, \'\\n\',\' \'), \'\\r\',\'\') ORDER_DETAIL_DISPLAY_LINE from thcdnadevdata.cerner_ods.cerner_orders_hist ORD_HIST  INNER join thcdnadevdata.idm.base_encounter_clinical BASE ON ORD_HIST.HEALTH_SYSTEM_SOURCE_ID = BASE.HEALTH_SYSTEM_SOURCE_ID AND ORD_HIST.ENCNTR_ID = BASE.ENCNTR_ID ',V_PROC_NAME,V_LOG_TABLE,V_RESULT);

if V_RESULT <> 'P' then
	RAISE USING message = V_RESULT;
end if;

CALL `thcdnadevdata.idm.execute_sql`('CREATE TABLE IF NOT EXISTS thcdnadevdata.idm.dmc_ord_encntr AS SELECT DISTINCT ORD_HIST.CATALOG_TYPE_CD,ORD_HIST.DCP_CLIN_CAT_CD,ORD_HIST.SYNONYM_ID,ORD_HIST.CATALOG_CD, ORD_HIST.HEALTH_SYSTEM_SOURCE_ID,regexp_replace(regexp_replace(ORD_HIST.ORDER_DETAIL_DISPLAY_LINE, \'\\n\',\' \'), \'\\r\',\'\') ORDER_DETAIL_DISPLAY_LINE from thcdnadevdata.cerner_ods.dmc_orders_hist ORD_HIST  INNER join thcdnadevdata.idm.base_encounter_clinical BASE ON ORD_HIST.HEALTH_SYSTEM_SOURCE_ID = BASE.HEALTH_SYSTEM_SOURCE_ID AND ORD_HIST.ENCNTR_ID = BASE.ENCNTR_ID ',V_PROC_NAME,V_LOG_TABLE,V_RESULT);

if V_RESULT <> 'P' then
	RAISE USING message = V_RESULT;
end if;

CALL `thcdnadevdata.idm.execute_sql`('drop table if exists thcdnadevdata.idm.'||substr(V_PROC_NAME,8)||'_swap_temp1',V_PROC_NAME,V_LOG_TABLE,V_RESULT);
if V_RESULT <> 'P' then
	RAISE USING message = V_RESULT;
end if;

CALL `thcdnadevdata.idm.execute_sql`('CREATE TABLE thcdnadevdata.idm.'||substr(V_PROC_NAME,8)||'_swap_temp1  like  thcdnadevdata.idm.'||substr(V_PROC_NAME,8)||'   ',V_PROC_NAME,V_LOG_TABLE,V_RESULT);
if V_RESULT <> 'P' then
	RAISE USING message = V_RESULT;
end if;

CALL `thcdnadevdata.idm.execute_sql`(
-- Start of Argument 1 for execute_sql
CONCAT("""
INSERT INTO thcdnadevdata.idm.""",substr(V_PROC_NAME,8),"""_swap_temp1
 (DIM_ORDER_SK, ORDER_NM, ORDER_DESC, ORDER_TYPE, ORDER_CATALOG_TYPE, ORDER_CATALOG_DESC, MULTUM_CD, SOURCE_SYSTEM, CREATE_TS, CREATE_UID, UPDATE_TS, UPDATE_UID, UNIQUE_ID)
WITH
-- Pre-process cerner_order_catalog_hist to calculate cki_modified once.
-- This is identical to a subquery in the original, but extracted for clarity and to prevent re-computation.
cerner_catalog_hist_prepped AS (
  SELECT
    HEALTH_SYSTEM_SOURCE_ID,
    CATALOG_CD,
    UPPER(DESCRIPTION) AS DESCRIPTION,
    -- This window function was inside the original join subquery.
    MAX(CASE WHEN cki = '' THEN NULL ELSE cki END) OVER(PARTITION BY UPPER(DESCRIPTION)) AS cki_modified
  FROM
    `thcdnadevdata.cerner_ods.cerner_order_catalog_hist`
),
-- Pre-process dmc_order_catalog_hist similarly.
dmc_catalog_hist_prepped AS (
  SELECT
    HEALTH_SYSTEM_SOURCE_ID,
    CATALOG_CD,
    UPPER(DESCRIPTION) AS DESCRIPTION,
    MAX(CASE WHEN cki = '' THEN NULL ELSE cki END) OVER(PARTITION BY UPPER(DESCRIPTION)) AS cki_modified
  FROM
    `thcdnadevdata.cerner_ods.dmc_order_catalog_hist`
),
-- Process and transform the 'CERNER' source data.
-- The SELECT DISTINCT here matches the original query's logic within the first part of the UNION ALL.
cerner_source AS (
  SELECT DISTINCT
    UPPER(IFNULL(LTRIM(RTRIM(CAT_SYN_HIST.MNEMONIC)), 'N/A')) AS ORDER_NM,
    UPPER(IFNULL(LTRIM(RTRIM(ORD_HIST.ORDER_DETAIL_DISPLAY_LINE)), 'N/A')) AS ORDER_DESC,
    UPPER(IFNULL(LTRIM(RTRIM(CODE_VALUE.DISPLAY)), 'N/A')) AS ORDER_TYPE,
    UPPER(IFNULL(LTRIM(RTRIM(CODE_VALUE1.DISPLAY)), 'N/A')) AS ORDER_CATALOG_TYPE,
    UPPER(IFNULL(LTRIM(RTRIM(CAT_HIST.DESCRIPTION)), 'N/A')) AS ORDER_CATALOG_DESC,
    LTRIM(RTRIM(SUBSTR(CAT_HIST.cki_modified, INSTR(CAT_HIST.cki_modified, '!') + 1))) AS MULTUM_CD,
    'CERNER' AS SOURCE_SYSTEM
  FROM
    `thcdnadevdata.idm.cerner_ord_encntr` AS ORD_HIST
    LEFT JOIN cerner_catalog_hist_prepped AS CAT_HIST
      ON ORD_HIST.HEALTH_SYSTEM_SOURCE_ID = CAT_HIST.HEALTH_SYSTEM_SOURCE_ID AND ORD_HIST.CATALOG_CD = CAT_HIST.CATALOG_CD
    LEFT JOIN `thcdnadevdata.cerner_ods.cerner_order_catalog_synonym_hist` AS CAT_SYN_HIST
      ON ORD_HIST.HEALTH_SYSTEM_SOURCE_ID = CAT_SYN_HIST.HEALTH_SYSTEM_SOURCE_ID AND ORD_HIST.SYNONYM_ID = CAT_SYN_HIST.SYNONYM_ID
    LEFT JOIN `thcdnadevdata.cerner_ods.cerner_code_value_hist` AS CODE_VALUE
      ON ORD_HIST.HEALTH_SYSTEM_SOURCE_ID = CODE_VALUE.HEALTH_SYSTEM_SOURCE_ID AND ORD_HIST.DCP_CLIN_CAT_CD = CODE_VALUE.CODE_VALUE
    LEFT JOIN `thcdnadevdata.cerner_ods.cerner_code_value_hist` AS CODE_VALUE1
      ON ORD_HIST.HEALTH_SYSTEM_SOURCE_ID = CODE_VALUE1.HEALTH_SYSTEM_SOURCE_ID AND ORD_HIST.CATALOG_TYPE_CD = CODE_VALUE1.CODE_VALUE
),
-- Process and transform the 'DMC_CERNER' source data.
-- The SELECT DISTINCT here matches the original query's logic within the second part of the UNION ALL.
dmc_source AS (
  SELECT DISTINCT
    UPPER(IFNULL(LTRIM(RTRIM(CAT_SYN_HIST.MNEMONIC)), 'N/A')) AS ORDER_NM,
    UPPER(IFNULL(LTRIM(RTRIM(ORD_HIST.ORDER_DETAIL_DISPLAY_LINE)), 'N/A')) AS ORDER_DESC,
    UPPER(IFNULL(LTRIM(RTRIM(CODE_VALUE.DISPLAY)), 'N/A')) AS ORDER_TYPE,
    UPPER(IFNULL(LTRIM(RTRIM(CODE_VALUE1.DISPLAY)), 'N/A')) AS ORDER_CATALOG_TYPE,
    UPPER(IFNULL(LTRIM(RTRIM(CAT_HIST.DESCRIPTION)), 'N/A')) AS ORDER_CATALOG_DESC,
    LTRIM(RTRIM(SUBSTR(CAT_HIST.cki_modified, INSTR(CAT_HIST.cki_modified, '!') + 1))) AS MULTUM_CD,
    'DMC_CERNER' AS SOURCE_SYSTEM
  FROM
    `thcdnadevdata.idm.dmc_ord_encntr` AS ORD_HIST
    LEFT JOIN dmc_catalog_hist_prepped AS CAT_HIST
      ON ORD_HIST.HEALTH_SYSTEM_SOURCE_ID = CAT_HIST.HEALTH_SYSTEM_SOURCE_ID AND ORD_HIST.CATALOG_CD = CAT_HIST.CATALOG_CD
    LEFT JOIN `thcdnadevdata.cerner_ods.dmc_order_catalog_synonym_hist` AS CAT_SYN_HIST
      ON ORD_HIST.HEALTH_SYSTEM_SOURCE_ID = CAT_SYN_HIST.HEALTH_SYSTEM_SOURCE_ID AND ORD_HIST.SYNONYM_ID = CAT_SYN_HIST.SYNONYM_ID
    LEFT JOIN `thcdnadevdata.cerner_ods.dmc_code_value_hist` AS CODE_VALUE
      ON ORD_HIST.HEALTH_SYSTEM_SOURCE_ID = CODE_VALUE.HEALTH_SYSTEM_SOURCE_ID AND ORD_HIST.DCP_CLIN_CAT_CD = CODE_VALUE.CODE_VALUE
    LEFT JOIN `thcdnadevdata.cerner_ods.dmc_code_value_hist` AS CODE_VALUE1
      ON ORD_HIST.HEALTH_SYSTEM_SOURCE_ID = CODE_VALUE1.HEALTH_SYSTEM_SOURCE_ID AND ORD_HIST.CATALOG_TYPE_CD = CODE_VALUE1.CODE_VALUE
),
-- Combine the two distinct source sets. This is equivalent to the original UNION ALL.
combined_distinct_sources AS (
  SELECT * FROM cerner_source
  UNION ALL
  SELECT * FROM dmc_source
),
-- Apply the final deduplication rule: for any identical record, prefer the 'CERNER' source.
final_deduplicated_rows AS (
  SELECT
    *,
    ROW_NUMBER() OVER (
      PARTITION BY ORDER_NM, ORDER_DESC, ORDER_TYPE, ORDER_CATALOG_TYPE, ORDER_CATALOG_DESC, MULTUM_CD
      ORDER BY SOURCE_SYSTEM ASC NULLS LAST
    ) AS rn
  FROM combined_distinct_sources
)
-- Final projection for insertion.
SELECT
  """,V_DIM_ORDER_SK_MAX,""" + ROW_NUMBER() OVER () AS DIM_ORDER_SK,
  ORDER_NM,
  ORDER_DESC,
  ORDER_TYPE,
  ORDER_CATALOG_TYPE,
  ORDER_CATALOG_DESC,
  MULTUM_CD,
  SOURCE_SYSTEM,
  CURRENT_DATETIME('America/Chicago') AS CREATE_TS,
  SESSION_USER() AS CREATE_UID,
  CURRENT_DATETIME('America/Chicago') AS UPDATE_TS,
  SESSION_USER() AS UPDATE_UID,
  -- Note: The original UNIQUE_ID did not include MULTUM_CD. Replicating that behavior.
  CONCAT(
    ORDER_NM, '~',
    ORDER_DESC, '~',
    ORDER_TYPE, '~',
    ORDER_CATALOG_TYPE, '~',
    ORDER_CATALOG_DESC, '~',
    SOURCE_SYSTEM
  ) AS UNIQUE_ID
FROM final_deduplicated_rows
WHERE
  rn = 1 """), V_PROC_NAME, V_LOG_TABLE, V_RESULT
);
if V_RESULT <> 'P' then 
	SET V_ERROR_MESSAGE = V_RESULT;
--SELECT 'Exception: ', V_RESULT
 RAISE USING message = V_RESULT;
 end if;

CALL `thcdnadevdata.idm.execute_sql`('DELETE FROM thcdnadevdata.idm.'||substr(V_PROC_NAME,8)||'_swap_temp1 A where exists ( select 1 from thcdnadevdata.idm.'||substr(V_PROC_NAME,8)||' B where 1 =  1 and IFNULL(upper(ltrim(rtrim(A.ORDER_NM))),\'N/A\')=IFNULL(upper(ltrim(rtrim(B.ORDER_NM))),\'N/A\') and  IFNULL(upper(ltrim(rtrim(A.ORDER_DESC))),\'N/A\')=IFNULL(upper(ltrim(rtrim(B.ORDER_DESC))),\'N/A\')	 and  IFNULL(upper(ltrim(rtrim(A.ORDER_TYPE))),\'N/A\')=IFNULL(upper(ltrim(rtrim(B.ORDER_TYPE))),\'N/A\') and  IFNULL(upper(ltrim(rtrim(A.ORDER_CATALOG_TYPE))),\'N/A\')=IFNULL(upper(ltrim(rtrim(B.ORDER_CATALOG_TYPE))),\'N/A\') and  IFNULL(upper(ltrim(rtrim(A.ORDER_CATALOG_DESC))),\'N/A\')=IFNULL(upper(ltrim(rtrim(B.ORDER_CATALOG_DESC))),\'N/A\') ) ',V_PROC_NAME,V_LOG_TABLE,V_RESULT);
if V_RESULT <> 'P' then
	RAISE USING message = V_RESULT;
end if;


INSERT INTO thcdnadevdata.idm.dim_order_swap_temp1 (
    dim_order_sk,
    order_nm,
    order_desc,
    order_type,
    order_catalog_type,
    order_catalog_desc,
    multum_cd,
    source_system,
    create_ts,
    create_uid,
    update_ts,
    update_uid,
    unique_id
)
SELECT
    dim_order_sk,
    order_nm,
    order_desc,
    order_type,
    order_catalog_type,
    order_catalog_desc,
    multum_cd,
    source_system,
    create_ts,
    create_uid,
    update_ts,
    update_uid,
    unique_id
FROM
    thcdnadevdata.idm.dim_order AS F;
if V_RESULT <> 'P' then
	RAISE USING message = V_RESULT;
end if;

CALL `thcdnadevdata.idm.execute_sql`('DROP TABLE IF EXISTS thcdnadevdata.idm.'||substr(V_PROC_NAME,8)||'_old',V_PROC_NAME,V_LOG_TABLE,V_RESULT);
if V_RESULT <> 'P' then
	RAISE USING message = V_RESULT;
end if;

CALL `thcdnadevdata.idm.execute_sql`('ALTER TABLE thcdnadevdata.idm.'||substr(V_PROC_NAME,8)||' RENAME TO '||substr(V_PROC_NAME,8)||'_old',V_PROC_NAME,V_LOG_TABLE,V_RESULT);
if V_RESULT <> 'P' then
	RAISE USING message = V_RESULT;
end if;
CALL `thcdnadevdata.idm.execute_sql`('ALTER TABLE thcdnadevdata.idm.'||substr(V_PROC_NAME,8)||'_swap_temp1 RENAME TO '||substr(V_PROC_NAME,8),V_PROC_NAME,V_LOG_TABLE,V_RESULT);
if V_RESULT <> 'P' then
	RAISE USING message = V_RESULT;
end if;

--********************************DIM LOAD END*****************************************************************

/*** Logging to SP_LOG and exception handling*/

if V_RESULT <> 'P' then
	SET V_ERROR_MESSAGE = V_RESULT;
else
	SET V_ERROR_MESSAGE = @@error.message;
end if;

set V_END_TS = CURRENT_DATETIME("America/Chicago");
SET V_END_TS_TEXT = FORMAT_DATETIME('%Y%m%d %H:%M:%E*S',V_END_TS);
SELECT 'V_LOG_TABLE:', V_LOG_TABLE;
SELECT 'V_START_TS_TEXT:', V_START_TS_TEXT;
SELECT 'V_END_TS_TEXT:', V_END_TS_TEXT;
SELECT 'V_ERROR_MESSAGE:', V_ERROR_MESSAGE;

SET V_SQL_LOG = 'insert into '||V_LOG_TABLE||'(RECORD_TYPE,SQL,ROWS_MODIFIED,SP_NAME,START_TS,END_TS,ERROR_MSG,LOG_TABLE_NAME,SESSION_ID,PID,CONNECT_TIME,PRIORITY,PRIORITY_NAME,MAX_PRIORITY,MAX_PRIORITY_NAME,DB_OID,SESSION_USER_ID,CURRENT_USER_ID,SESSION_USER_OID,CURRENT_USER_OID,OPERATING_USER_OID,SESSION_USERNAME,CURRENT_USERNAME,OPERATING_USERNAME,DBNAME,CLIENT_HOST,CLIENT_IP,CLIENT_PID,CLIENT_TYPE,CLIENT_TYPE_NAME,CLIENT_ID,SESSION_SOURCE,SESSION_SOURCE_NAME,SESSION_STATE,SESSION_STATE_NAME,ROWSET_LIMIT,SESSION_TIMEOUT,QUERY_TIMEOUT,SER_QUEUE_TIMEOUT,MAX_QUERY_RESTARTS,COLLECT_HISTORY,CROSS_JOIN_ALLOWED,RESOURCE_GROUP_OID,RESOURCE_GROUP,RESOURCE_PERCENTAGE,SQLTEXT,COMMENT,OPID) select \'SP\' RECORD_TYPE ,\''||V_PROC_NAME||'|'||COALESCE(replace(v_paremeter_list,'\'','\'\''),'No Parameters')||'\' SQL ,0 ROWS_MODIFIED ,\''||V_PROC_NAME||'\' SP_NAME ,PARSE_DATETIME(\'%Y%m%d %H%M%E*S\',\''||REPLACE(v_start_ts_text,":","")|| '\') start_ts ,PARSE_DATETIME(\'%Y%m%d %H%M%E*S\',\''||REPLACE(v_end_ts_text,":","")|| '\') end_ts,\''||COALESCE(replace(V_ERROR_MESSAGE,'\'','\'\''),'No Error')||'\' ERROR_MSG,\''||V_LOG_TABLE||'\' log_table_name , null as SESSION_ID , null PID ,cast(creation_time as datetime) ,null as PRIORITY , "" as PRIORITY_NAME , "" as MAX_PRIORITY , "" as MAX_PRIORITY_NAME , "" as DB_OID , "" as  SESSION_USER_ID , "" as  CURRENT_USER_ID , "" as  SESSION_USER_OID , "" as CURRENT_USER_OID , "" as OPERATING_USER_OID , "" as  SESSION_USERNAME , "" as CURRENT_USERNAME , "" as OPERATING_USERNAME , "" as DBNAME , "" as CLIENT_HOST , "" as CLIENT_IP ,"" as CLIENT_PID , null as CLIENT_TYPE , "" as CLIENT_TYPE_NAME , null as CLIENT_ID , null as SESSION_SOURCE , "" as SESSION_SOURCE_NAME ,NULL as SESSION_STATE ,"" as SESSION_STATE_NAME ,"" as ROWSET_LIMIT ,"" as  SESSION_TIMEOUT ,"" as QUERY_TIMEOUT ,"" as SER_QUEUE_TIMEOUT , "" as MAX_QUERY_RESTARTS ,null as COLLECT_HISTORY ,"" as CROSS_JOIN_ALLOWED ,"" as RESOURCE_GROUP_OID ,"" as RESOURCE_GROUP ,"" as RESOURCE_PERCENTAGE ,query , "" as COMMENT , "" as OPID from `region-us-central1`.INFORMATION_SCHEMA.JOBS_BY_PROJECT where 1 = 1 and query like \'%'||V_PROC_NAME||'%'||replace(COALESCE(replace(V_PAREMETER_LIST,'\'','\'\''),'%'),'|','%')||'%\'';

SELECT 'V_SQL_LOG:', V_SQL_LOG;
execute immediate V_SQL_LOG;
SELECT 'ROW_COUNT:', @@ROW_COUNT;

execute immediate 'insert into thcdnadevdata.idm.sp_log select * from '||V_LOG_TABLE;

SET OUT_PARAM = 1;
SELECT OUT_PARAM;
return;
SELECT 'Normal End.';

EXCEPTION WHEN ERROR THEN
SELECT 'Exception.';
if V_RESULT <> 'P' then
SET V_ERROR_MESSAGE = V_RESULT;
else 
SET V_ERROR_MESSAGE = @@error.message;
end if;
SET V_END_TS = CURRENT_DATETIME("America/Chicago");
SET V_END_TS_TEXT = FORMAT_DATETIME('%Y%m%d %H:%M:%E*S',V_END_TS);
SELECT 'V_LOG_TABLE:', V_LOG_TABLE;
SELECT 'V_START_TS_TEXT:', V_START_TS_TEXT;
SELECT 'V_END_TS_TEXT:', V_END_TS_TEXT;
SELECT 'V_ERROR_MESSAGE:', V_ERROR_MESSAGE;

SET V_SQL_LOG = 'insert into '||V_LOG_TABLE||'(RECORD_TYPE,SQL,ROWS_MODIFIED,SP_NAME,START_TS,END_TS,ERROR_MSG,LOG_TABLE_NAME,SESSION_ID,PID,CONNECT_TIME,PRIORITY,PRIORITY_NAME,MAX_PRIORITY,MAX_PRIORITY_NAME,DB_OID,SESSION_USER_ID,CURRENT_USER_ID,SESSION_USER_OID,CURRENT_USER_OID,OPERATING_USER_OID,SESSION_USERNAME,CURRENT_USERNAME,OPERATING_USERNAME,DBNAME,CLIENT_HOST,CLIENT_IP,CLIENT_PID,CLIENT_TYPE,CLIENT_TYPE_NAME,CLIENT_ID,SESSION_SOURCE,SESSION_SOURCE_NAME,SESSION_STATE,SESSION_STATE_NAME,ROWSET_LIMIT,SESSION_TIMEOUT,QUERY_TIMEOUT,SER_QUEUE_TIMEOUT,MAX_QUERY_RESTARTS,COLLECT_HISTORY,CROSS_JOIN_ALLOWED,RESOURCE_GROUP_OID,RESOURCE_GROUP,RESOURCE_PERCENTAGE,SQLTEXT,COMMENT,OPID) select \'SP\' RECORD_TYPE ,\''||V_PROC_NAME||'|'||COALESCE(replace(v_paremeter_list,'\'','\'\''),'No Parameters')||'\' SQL ,0 ROWS_MODIFIED ,\''||V_PROC_NAME||'\' SP_NAME ,PARSE_DATETIME(\'%Y%m%d %H%M%E*S\',\''||REPLACE(v_start_ts_text,":","")|| '\') start_ts ,PARSE_DATETIME(\'%Y%m%d %H%M%E*S\',\''||REPLACE(v_end_ts_text,":","")|| '\') end_ts,\''||COALESCE(replace(V_ERROR_MESSAGE,'\'','\'\''),'No Error')||'\' ERROR_MSG,\''||V_LOG_TABLE||'\' log_table_name , null as SESSION_ID , null PID ,cast(creation_time as datetime) ,null as PRIORITY , "" as PRIORITY_NAME , "" as MAX_PRIORITY , "" as MAX_PRIORITY_NAME , "" as DB_OID , "" as  SESSION_USER_ID , "" as  CURRENT_USER_ID , "" as  SESSION_USER_OID , "" as CURRENT_USER_OID , "" as OPERATING_USER_OID , "" as  SESSION_USERNAME , "" as CURRENT_USERNAME , "" as OPERATING_USERNAME , "" as DBNAME , "" as CLIENT_HOST , "" as CLIENT_IP ,"" as CLIENT_PID , null as CLIENT_TYPE , "" as CLIENT_TYPE_NAME , null as CLIENT_ID , null as SESSION_SOURCE , "" as SESSION_SOURCE_NAME ,NULL as SESSION_STATE ,"" as SESSION_STATE_NAME ,"" as ROWSET_LIMIT ,"" as  SESSION_TIMEOUT ,"" as QUERY_TIMEOUT ,"" as SER_QUEUE_TIMEOUT , "" as MAX_QUERY_RESTARTS ,null as COLLECT_HISTORY ,"" as CROSS_JOIN_ALLOWED ,"" as RESOURCE_GROUP_OID ,"" as RESOURCE_GROUP ,"" as RESOURCE_PERCENTAGE ,query , "" as COMMENT , "" as OPID from `region-us-central1`.INFORMATION_SCHEMA.JOBS_BY_PROJECT where 1 = 1 and query like \'%'||V_PROC_NAME||'%'||replace(COALESCE(replace(V_PAREMETER_LIST,'\'','\'\''),'%'),'|','%')||'%\'';
SELECT 'V_SQL_LOG:', V_SQL_LOG;
execute immediate V_SQL_LOG;
SELECT 'ROW_COUNT:', @@ROW_COUNT;
execute immediate 'insert into thcdnadevdata.idm.sp_log select * from '||v_log_table;

--SELECT 'Exception: %', V_ERROR_MESSAGE ; 

SET OUT_PARAM = 0;
SELECT OUT_PARAM;
RAISE USING message = V_ERROR_MESSAGE;
END;
END;

CREATE OR REPLACE PROCEDURE `thcdnadevdata.idm.sp_cnl_fact_laboratory_opti`(IN SQL1 DATE, OUT OUT_PARAM INT64)
BEGIN

 DECLARE I_PROCESS_DT STRING;
 DECLARE V_PROCESS_DT STRING; 
 DECLARE V_LOG_TABLE STRING; 
 DECLARE V_START_TS DATETIME; 
 DECLARE V_END_TS DATETIME; 
 DECLARE V_START_TS_TEXT STRING; 
 DECLARE V_END_TS_TEXT STRING; 
 DECLARE V_PROC_NAME STRING; 
 DECLARE V_RAND_NBR INT64; 
 DECLARE V_ERROR_MESSAGE STRING; 
 DECLARE V_SQL_START_TS DATETIME; 
 DECLARE V_SQL_END_TS DATETIME; 
 DECLARE V_ROW_COUNT INT64; 
 DECLARE V_SQL_START_TS_TEXT STRING; 
 DECLARE V_SQL_END_TS_TEXT STRING;
 DECLARE V_SQL_LOG STRING; 
 DECLARE V_LOG_TS_TEXT STRING; 
 DECLARE V_RESULT STRING; 
 DECLARE V_PAREMETER_LIST STRING; 
 DECLARE V_CNT INT64; 
 DECLARE V_RECORD STRUCT<>; 

-- declare  SQL1 STRING default '2022-12-12';
-- declare OUT_PARAM STRING;


 SET I_PROCESS_DT = format_date('%Y-%m-%d',SQL1);

 BEGIN 

 SET V_START_TS = CURRENT_DATETIME("America/Chicago"); 
 SELECT  'Procedure Starting.';
 SET  V_START_TS_TEXT = FORMAT_DATETIME('%Y%m%d %H:%M:%E*S',V_START_TS);
 SET  V_LOG_TS_TEXT = REPLACE(FORMAT_DATETIME('%Y%m%d%H%M%E*S',V_START_TS),'.','');
 SET  V_PROC_NAME = 'sp_cnl_fact_laboratory'; 
 SET  V_RAND_NBR = CAST(rand()*pow(10,15) AS INT64);
 SET  V_PROCESS_DT = I_PROCESS_DT; 

  SELECT  'V_PROCESS_DT:', V_PROCESS_DT; 
  SET V_LOG_TABLE = 'TEMP_LOG_'||V_LOG_TS_TEXT||'_'||V_RAND_NBR; 
  SELECT  'V_PROCESS_DT:', V_LOG_TABLE; 
  SET V_PAREMETER_LIST =V_PROCESS_DT; 
  execute immediate 'create temporary table '||V_LOG_TABLE||' as select * FROM thcdnadevdata.idm.sp_log where 1 = 2'; 
  SELECT  'V_PROCESS_DT:', V_PROC_NAME; 
  SELECT  'V_PROCESS_DT:', V_LOG_TABLE;

  CALL `thcdnadevdata.idm.execute_sql`('DROP TABLE IF EXISTS thcdnadevdata.idm.fact_laboratory_sunquest_ref_lab ',V_PROC_NAME,V_LOG_TABLE,V_RESULT);
  IF V_RESULT <> 'P' THEN RAISE USING message = V_RESULT; END IF; 

  CALL `thcdnadevdata.idm.execute_sql`('DROP TABLE  IF EXISTS thcdnadevdata.idm.fact_laboratory_lab_performing_partner ',V_PROC_NAME,V_LOG_TABLE,V_RESULT); 
  IF V_RESULT <> 'P' THEN RAISE USING message = V_RESULT; END IF;

  CALL `thcdnadevdata.idm.execute_sql`('DROP TABLE IF EXISTS thcdnadevdata.idm.fact_laboratory_lab_location ',V_PROC_NAME,V_LOG_TABLE,V_RESULT);
  IF V_RESULT <> 'P' THEN RAISE USING message = V_RESULT; END IF; 

  CALL `thcdnadevdata.idm.execute_sql`('DROP TABLE IF EXISTS thcdnadevdata.idm.fact_laboratory_temp1 ',V_PROC_NAME,V_LOG_TABLE,V_RESULT);
  IF V_RESULT <> 'P' THEN RAISE USING message = V_RESULT; END IF;

CALL `thcdnadevdata.idm.execute_sql`(' CREATE TABLE IF NOT EXISTS thcdnadevdata.idm.fact_laboratory_sunquest_ref_lab AS  SELECT   PTNUMBER,   PTORDACCOUNT,   PTNAME,   PTSEX,   BIRTHDATE_ODBC,   PTLOCNAME,   ORDERPHYSNAME,   TESTNAME,   RESULT,   resunits,   RESULTNORMRNG,   verifyrange,   RESULTQAFLAGS,   ACCNUMBER,   CURRENTRESULT,   orderdate_ts,   collect_ts,   receive_ts,   result_ts FROM (   SELECT     PTNUMBER,     PTORDACCOUNT,     PTNAME,     PTSEX,     BIRTHDATE_ODBC,     PTLOCNAME,     ORDERPHYSNAME,     TESTNAME,     RESULT,     units.resunits,     RESULTNORMRNG,     verifyrange,     RESULTQAFLAGS,     ACCNUMBER,     CURRENTRESULT,     PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\',FORMAT_DATETIME(\'%Y-%m-%d\',orderdateodbc)||\' \'||ordertimeodbc) orderdate_ts,     PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\',FORMAT_DATETIME(\'%Y-%m-%d\',COLLECTDATEODBC)||\' \'||COLLECTTIMEODBC ) collect_ts,     PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\',FORMAT_DATETIME(\'%Y-%m-%d\',RECEIVEDATEODBC)||\' \'||RECEIVETIMEODBC) receive_ts,     PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\',FORMAT_DATETIME(\'%Y-%m-%d\',RESULTDATEODBC)||\' \'||RESULTTIMEODBC) result_ts,     ROW_NUMBER() OVER (PARTITION BY SUNQUEST_U_DMC_GLRES_VIEW.RNK     ORDER BY       CASE         WHEN 1.0*age > CASE         WHEN collectage LIKE \'%D%\'       AND CAST(SUBSTR(collectage,1,LENGTH(collectage)-1) AS INT64) < 15 THEN 0.00         WHEN collectage LIKE \'%D%\' THEN ROUND(CAST(SUBSTR(collectage,1,LENGTH(collectage)-1) AS numeric)/30.0,1)         WHEN collectage LIKE \'%M%\' THEN CAST(SUBSTR(collectage,1,LENGTH(collectage)-1) AS numeric)         WHEN collectage = \'Unknown\' THEN NULL       ELSE       CAST(collectage AS numeric)*12     END       THEN 0       ELSE       1     END       ASC     NULLS LAST       ,       ABS(         CASE           WHEN collectage LIKE \'%D%\' AND CAST(SUBSTR(collectage,1,LENGTH(collectage)-1) AS INT64) < 15 THEN 0.00           WHEN collectage LIKE \'%D%\' THEN ROUND(CAST(SUBSTR(collectage,1,LENGTH(collectage)-1) AS numeric)/30.0,1)           WHEN collectage LIKE \'%M%\' THEN CAST(SUBSTR(collectage,1,LENGTH(collectage)-1) AS numeric)           WHEN collectage = \'Unknown\' THEN NULL         ELSE         CAST(collectage AS numeric)*12       END         - 1.0*age) ASC     NULLS LAST       ,       CAST(age AS numeric) DESC     NULLS LAST       ) pick_1   FROM     (select ROW_NUMBER() OVER () RNK,* FROM thcdnadevdata.cerner_ods.sunquest_u_dmc_glres_view) SUNQUEST_U_DMC_GLRES_VIEW   LEFT OUTER JOIN (     SELECT       ma_ordcode,       resunits     FROM (       SELECT         ma_ordcode,         resunits,         ROW_NUMBER() OVER (PARTITION BY ma_ordcode ORDER BY enddatestatus DESC NULLS LAST , counts DESC NULLS LAST ) pick_pop       FROM (         SELECT           ma_ordcode,           UPPER(testunits) resunits,           enddatestatus,           COUNT(*) OVER (PARTITION BY ma_ordcode) counts         FROM           thcdnadevdata.cerner_ods.sunquest_ma_qamethrng_view         WHERE           1 = 1 ) moo2 ) SUNQUEST_U_DMC_GLRES_VIEW1     WHERE       pick_pop = 1 ) units   ON     ( 1 = 1       AND units.ma_ordcode = testcode )   LEFT OUTER JOIN     thcdnadevdata.cerner_ods.sunquest_ma_qamethrng_view   ON     ( 1 = 1       AND SUNQUEST_U_DMC_GLRES_VIEW.testcode = SUNQUEST_MA_QAMETHRNG_VIEW.ma_ordcode       AND SUNQUEST_U_DMC_GLRES_VIEW.ptsex = SUNQUEST_MA_QAMETHRNG_VIEW.sex )   WHERE     1 = 1     AND hospcode = \'LN\' ) moo2 WHERE   1 = 1 AND  pick_1 = 1 ', V_PROC_NAME,V_LOG_TABLE, V_RESULT);
 if v_result <> 'P' then RAISE USING message = V_RESULT; end if;

  CALL `thcdnadevdata.idm.execute_sql`('CREATE TABLE thcdnadevdata.idm.fact_laboratory_lab_location cluster by health_system_source_id,order_id AS ( select distinct health_system_source_id,order_id,inn.facility_cd,lab_location, COALESCE(loc.DIM_LOCATION_SK,-99) DIM_LAB_LOCATION_SK   from 	( select * from  ( select base.facility_cd, charge.health_system_source_id,charge.order_id,display lab_location  ,row_number() over (partition by charge.health_system_source_id,charge.order_id order by case when charge.department_cd = 0 then 0 else 1 end desc nulls last,charge.activity_dt_tm desc nulls last,charge.charge_item_id desc nulls last) pick_1               FROM thcdnadevdata.cerner_ods.cerner_charge_hist charge 			  inner JOIN thcdnadevdata.cerner_ods.cerner_code_value_hist code_value 			  ON  1 =  1               and charge.health_system_source_id = code_value.health_system_source_id               and charge.department_cd = code_value.code_value 			  inner JOIN thcdnadevdata.idm.base_encounter_clinical base 			  ON base.health_system_source_id = charge.health_system_source_id 			  and base.encntr_id = charge.encntr_id                       ) charge        where pick_1 = 1 	   ) inn 	   left outer join (select * FROM thcdnadevdata.idm.dim_location where LOCATION_TYPE=\'LAB LOCATION\')  loc 	   ON upper(inn.facility_cd) = upper(loc.FACILITY_CD) 	   and COALESCE(upper(ltrim(rtrim(inn.lab_location))),\'N/A\')=COALESCE(upper(ltrim(rtrim(loc.LOCATION_CD))),\'N/A\') )  ',V_PROC_NAME,V_LOG_TABLE,V_RESULT); 
  if v_result <> 'P' then RAISE USING message = V_RESULT; end if;

-- CALL `thcdnadevdata.idm.execute_sql`('CREATE TABLE thcdnadevdata.idm.fact_laboratory_temp1 AS ( SELECT   base.DIM_FACILITY_SK,  base.DIM_PATIENT_SK, base.DIM_ORDER_SK DIM_ORDER_SK,       base.DIM_ORDERING_PHYSICIAN_SK DIM_ORDERING_PHYSICIAN_SK,       base.DIM_ORDER_LOCATION_SK DIM_ORDER_LOCATION_SK,       base.DIM_MEASURING_UNIT_SK DIM_MEASURING_UNIT_SK,       base.DIM_RESULT_TYPE_SK DIM_RESULT_TYPE_SK,       base.FACT_ORDER_SK FACT_ORDER_SK,       base.PATIENT_ACCOUNT_NBR PATIENT_ACCOUNT_NBR,       base.FACILITY_CD,       staging.convert_timezone(ORDERS.ORIG_ORDER_DT_TM,         CAST(CASE WHEN fac.DST_IND=\'Y\' THEN 1 WHEN fac.DST_IND=\'N\' THEN 0 ELSE NULL END AS BOOLEAN),         fac.TM_ZONE_NM) AS ORDER_DT_TM,       staging.convert_timezone(ORDERS.DRAWN_DT_TM,         CAST(CASE WHEN fac.DST_IND=\'Y\' THEN 1 WHEN fac.DST_IND=\'N\' THEN 0 ELSE NULL END AS BOOLEAN),         fac.TM_ZONE_NM) AS DRAWN_TS,       staging.convert_timezone(ORDERS.RECEIVED_DT_TM,         CAST(CASE WHEN fac.DST_IND=\'Y\' THEN 1 WHEN fac.DST_IND=\'N\' THEN 0 ELSE NULL END AS BOOLEAN),         fac.TM_ZONE_NM) AS RECEIVE_TS,       staging.convert_timezone(base.ORDER_COMPLETE_TS,         CAST(CASE WHEN fac.DST_IND=\'Y\' THEN 1 WHEN fac.DST_IND=\'N\' THEN 0 ELSE NULL END AS BOOLEAN),         fac.TM_ZONE_NM) AS COMPLETE_TS,cast(ROUND(DATETIME_DIFF(staging.convert_timezone(ORDERS.DRAWN_DT_TM, CAST(CASE WHEN fac.DST_IND=\'Y\' THEN 1 WHEN fac.DST_IND=\'N\' THEN 0 ELSE NULL END AS BOOLEAN), fac.TM_ZONE_NM),staging.convert_timezone(ORDERS.ORIG_ORDER_DT_TM, CAST(CASE WHEN fac.DST_IND=\'Y\' THEN 1 WHEN fac.DST_IND=\'N\' THEN 0 ELSE NULL END AS BOOLEAN), fac.TM_ZONE_NM),SECOND)/60) AS float64) ORDER_TO_DRAWN_MINUTES, CASE WHEN staging.convert_timezone(ORDERS.DRAWN_DT_TM, CAST(CASE WHEN fac.DST_IND=\'Y\' THEN 1 WHEN fac.DST_IND=\'N\' THEN 0 ELSE NULL END AS BOOLEAN), fac.TM_ZONE_NM) < staging.convert_timezone(ORDERS.ORIG_ORDER_DT_TM, CAST(CASE WHEN fac.DST_IND=\'Y\' THEN 1 WHEN fac.DST_IND=\'N\' THEN 0 ELSE NULL END AS BOOLEAN), fac.TM_ZONE_NM) THEN cast(ROUND(DATETIME_DIFF(staging.convert_timezone(ORDERS.RECEIVED_DT_TM, CAST(CASE WHEN fac.DST_IND=\'Y\' THEN 1 WHEN fac.DST_IND=\'N\' THEN 0 ELSE NULL END AS BOOLEAN), fac.TM_ZONE_NM),staging.convert_timezone(ORDERS.ORIG_ORDER_DT_TM, CAST(CASE WHEN fac.DST_IND=\'Y\' THEN 1 WHEN fac.DST_IND=\'N\' THEN 0 ELSE NULL END AS BOOLEAN), fac.TM_ZONE_NM),SECOND)/60) AS float64) ELSE cast(ROUND(DATETIME_DIFF(staging.convert_timezone(ORDERS.RECEIVED_DT_TM, CAST(CASE WHEN fac.DST_IND=\'Y\' THEN 1 WHEN fac.DST_IND=\'N\' THEN 0 ELSE NULL END AS BOOLEAN), fac.TM_ZONE_NM),staging.convert_timezone(ORDERS.DRAWN_DT_TM, CAST(CASE WHEN fac.DST_IND=\'Y\' THEN 1 WHEN fac.DST_IND=\'N\' THEN 0 ELSE NULL END AS BOOLEAN), fac.TM_ZONE_NM),SECOND)/60) AS float64) END AS DRAWN_TO_RECEIVE_MINUTES, CASE WHEN staging.convert_timezone(ORDERS.RECEIVED_DT_TM, CAST(CASE WHEN fac.DST_IND=\'Y\' THEN 1 WHEN fac.DST_IND=\'N\' THEN 0 ELSE NULL END AS BOOLEAN), fac.TM_ZONE_NM) < staging.convert_timezone(ORDERS.ORIG_ORDER_DT_TM, CAST(CASE WHEN fac.DST_IND=\'Y\' THEN 1 WHEN fac.DST_IND=\'N\' THEN 0 ELSE NULL END AS BOOLEAN), fac.TM_ZONE_NM) THEN cast(ROUND(DATETIME_DIFF(staging.convert_timezone(base.ORDER_COMPLETE_TS, CAST(CASE WHEN fac.DST_IND=\'Y\' THEN 1 WHEN fac.DST_IND=\'N\' THEN 0 ELSE NULL END AS BOOLEAN), fac.TM_ZONE_NM),staging.convert_timezone(ORDERS.ORIG_ORDER_DT_TM, CAST(CASE WHEN fac.DST_IND=\'Y\' THEN 1 WHEN fac.DST_IND=\'N\' THEN 0 ELSE NULL END AS BOOLEAN), fac.TM_ZONE_NM),SECOND)/60) AS float64) ELSE cast(ROUND(DATETIME_DIFF(staging.convert_timezone(base.ORDER_COMPLETE_TS,CAST(CASE WHEN fac.DST_IND=\'Y\' THEN 1 WHEN fac.DST_IND=\'N\' THEN 0 ELSE NULL END AS BOOLEAN), fac.TM_ZONE_NM),staging.convert_timezone(ORDERS.RECEIVED_DT_TM, CAST(CASE WHEN fac.DST_IND=\'Y\' THEN 1 WHEN fac.DST_IND=\'N\' THEN 0 ELSE NULL END AS BOOLEAN), fac.TM_ZONE_NM),SECOND)/60) AS float64) END AS RECEIVE_TO_RESULT_MINUTES,           base.RESULT_VALUE , base.NORMAL_RANGE_LOW , base.NORMAL_RANGE_HIGH , base.CRITICAL_RANGE_LOW  , base.CRITICAL_RANGE_HIGH , base.IS_RESULT_ABNORMAL RESULT_ABNORMAL_FLG , base.ACCESSION_NBR ACCESSION_NBR , base.RESULT_STATUS 	, base.LOINC  , base.SOURCE_SYSTEM  , CURRENT_DATETIME("America/Chicago") CREATE_TS  , base.CREATE_UID ,      CURRENT_DATETIME("America/Chicago") UPDATE_TS , base.UPDATE_UID        , base.HEALTH_SYSTEM_SOURCE_ID||\'~\'||base.ORDER_ID||\'~\'||base.EVENT_CD  UNIQUE_ID       ,(CASE WHEN FACT_LABORATORY_TEMP_AMENDED1.event_id is not null THEN 1 else 0 END ) amended_flg ,       cast(case when count(*) over (partition by base.fact_order_sk) > 1 then 1 else 0 end as INT64) LAB_PANEL_FLG ,      IFNULL(charge.DIM_LAB_LOCATION_SK,-99) DIM_LAB_LOCATION_SK , CPT_MAP.CPT CPT FROM          (select * FROM thcdnadevdata.idm.base_clinical_result  base   where upper(base.RESULT_FLOWSHEET) = \'LABORATORY\'          and base.source_system = \'CERNER\')   base           inner JOIN thcdnadevdata.idm.dim_facility fac   On base.dim_facility_sk = fac.dim_facility_sk            left outer join (select  ORDERS.HEALTH_SYSTEM_SOURCE_ID,ORDERS.ORDER_ID,ORDERS.ORIG_ORDER_DT_TM,ORDER_CONTAINER_R.CONTAINER_ID, CONTAINER.DRAWN_DT_TM,CONTAINER.RECEIVED_DT_TM FROM thcdnadevdata.idm.fact_order_temp_order ORDERS  INNER JOIN thcdnadevdata.cerner_ods.cerner_order_container_r_hist  ORDER_CONTAINER_R ON ORDERS.HEALTH_SYSTEM_SOURCE_ID = ORDER_CONTAINER_R.HEALTH_SYSTEM_SOURCE_ID  AND ORDERS.ORDER_ID = ORDER_CONTAINER_R.ORDER_ID left outer JOIN thcdnadevdata.cerner_ods.cerner_container_hist  CONTAINER ON ORDER_CONTAINER_R.HEALTH_SYSTEM_SOURCE_ID = CONTAINER.HEALTH_SYSTEM_SOURCE_ID  AND ORDER_CONTAINER_R.CONTAINER_ID = CONTAINER.CONTAINER_ID where COLLECTION_STATUS_FLAG=1) ORDERS ON base.HEALTH_SYSTEM_SOURCE_ID = ORDERS.HEALTH_SYSTEM_SOURCE_ID  AND base.ORDER_ID = ORDERS.ORDER_ID left outer JOIN thcdnadevdata.idm.fact_laboratory_temp_amended1 on ( 1 =  1 and base.health_system_source_id = FACT_LABORATORY_TEMP_AMENDED1.health_system_source_id and base.event_id = FACT_LABORATORY_TEMP_AMENDED1.event_id ) left outer JOIN thcdnadevdata.idm.fact_laboratory_lab_location charge on (        1 =  1        and base.health_system_source_id = charge.health_system_source_id        and base.order_id = charge.order_id ) left outer JOIN thcdnadevdata.staging.ff_loinc_cpt_mapping CPT_MAP ON base.LOINC=CPT_MAP.LOINC union all  SELECT       base.DIM_FACILITY_SK,       base.DIM_PATIENT_SK,       base.DIM_ORDER_SK DIM_ORDER_SK,       base.DIM_ORDERING_PHYSICIAN_SK DIM_ORDERING_PHYSICIAN_SK,       base.DIM_ORDER_LOCATION_SK DIM_ORDER_LOCATION_SK,       base.DIM_MEASURING_UNIT_SK DIM_MEASURING_UNIT_SK,       base.DIM_RESULT_TYPE_SK DIM_RESULT_TYPE_SK,       base.FACT_ORDER_SK FACT_ORDER_SK,       base.PATIENT_ACCOUNT_NBR PATIENT_ACCOUNT_NBR,       base.FACILITY_CD,       COALESCE(SUNQUEST_U_DMC_REVERSE_GLRES.ORDER_TS,         staging.convert_timezone(ORDERS.ORIG_ORDER_DT_TM,           CAST(CASE WHEN fac.DST_IND=\'Y\' THEN 1 WHEN fac.DST_IND=\'N\' THEN 0 ELSE NULL END AS BOOLEAN),           fac.TM_ZONE_NM)) AS ORDER_DT_TM,       SUNQUEST_U_DMC_REVERSE_GLRES.COLLECT_TS AS DRAWN_TS,       SUNQUEST_U_DMC_REVERSE_GLRES.RECEIVE_TS AS RECEIVE_TS,       COALESCE(SUNQUEST_U_DMC_REVERSE_GLRES.RESULT_TS,         staging.convert_timezone(base.ORDER_COMPLETE_TS,           CAST(CASE WHEN fac.DST_IND=\'Y\' THEN 1 WHEN fac.DST_IND=\'N\' THEN 0 ELSE NULL END AS BOOLEAN),           fac.TM_ZONE_NM)) AS COMPLETE_TS,       cast(ROUND(DATETIME_DIFF(SUNQUEST_U_DMC_REVERSE_GLRES.COLLECT_TS,COALESCE(SUNQUEST_U_DMC_REVERSE_GLRES.ORDER_TS, staging.convert_timezone(ORDERS.ORIG_ORDER_DT_TM, CAST(CASE WHEN fac.DST_IND=\'Y\' THEN 1 WHEN fac.DST_IND=\'N\' THEN 0 ELSE NULL END AS BOOLEAN), fac.TM_ZONE_NM)),SECOND)/60) AS float64) ORDER_TO_DRAWN_MINUTES, CASE WHEN SUNQUEST_U_DMC_REVERSE_GLRES.COLLECT_TS  < COALESCE(SUNQUEST_U_DMC_REVERSE_GLRES.ORDER_TS, staging.convert_timezone(ORDERS.ORIG_ORDER_DT_TM, CAST(CASE WHEN fac.DST_IND=\'Y\' THEN 1 WHEN fac.DST_IND=\'N\' THEN 0 ELSE NULL END AS BOOLEAN), fac.TM_ZONE_NM)) THEN cast(ROUND(DATETIME_DIFF(SUNQUEST_U_DMC_REVERSE_GLRES.RECEIVE_TS,COALESCE(SUNQUEST_U_DMC_REVERSE_GLRES.ORDER_TS, staging.convert_timezone(ORDERS.ORIG_ORDER_DT_TM, CAST(CASE WHEN fac.DST_IND=\'Y\' THEN 1 WHEN fac.DST_IND=\'N\' THEN 0 ELSE NULL END AS BOOLEAN), fac.TM_ZONE_NM)),SECOND)/60) AS float64) ELSE cast(ROUND(DATETIME_DIFF(SUNQUEST_U_DMC_REVERSE_GLRES.RECEIVE_TS,SUNQUEST_U_DMC_REVERSE_GLRES.COLLECT_TS ,SECOND)/60) AS float64) END AS DRAWN_TO_RECEIVE_MINUTES, CASE WHEN SUNQUEST_U_DMC_REVERSE_GLRES.RECEIVE_TS < COALESCE(SUNQUEST_U_DMC_REVERSE_GLRES.ORDER_TS, staging.convert_timezone(ORDERS.ORIG_ORDER_DT_TM, CAST(CASE WHEN fac.DST_IND=\'Y\' THEN 1 WHEN fac.DST_IND=\'N\' THEN 0 ELSE NULL END AS BOOLEAN), fac.TM_ZONE_NM)) THEN cast(ROUND(DATETIME_DIFF(COALESCE(SUNQUEST_U_DMC_REVERSE_GLRES.RESULT_TS, staging.convert_timezone(base.ORDER_COMPLETE_TS, CAST(CASE WHEN fac.DST_IND=\'Y\' THEN 1 WHEN fac.DST_IND=\'N\' THEN 0 ELSE NULL END AS BOOLEAN), fac.TM_ZONE_NM)),COALESCE(SUNQUEST_U_DMC_REVERSE_GLRES.ORDER_TS, staging.convert_timezone(ORDERS.ORIG_ORDER_DT_TM, CAST(CASE WHEN fac.DST_IND=\'Y\' THEN 1 WHEN fac.DST_IND=\'N\' THEN 0 ELSE NULL END AS BOOLEAN), fac.TM_ZONE_NM)),SECOND)/60) AS float64) ELSE cast(ROUND(DATETIME_DIFF(COALESCE(SUNQUEST_U_DMC_REVERSE_GLRES.RESULT_TS, staging.convert_timezone(base.ORDER_COMPLETE_TS, CAST(CASE WHEN fac.DST_IND=\'Y\' THEN 1 WHEN fac.DST_IND=\'N\' THEN 0 ELSE NULL END AS BOOLEAN), fac.TM_ZONE_NM)),SUNQUEST_U_DMC_REVERSE_GLRES.RECEIVE_TS,SECOND)/60) AS float64) END AS RECEIVE_TO_RESULT_MINUTES,                 base.RESULT_VALUE , base.NORMAL_RANGE_LOW , base.NORMAL_RANGE_HIGH  , base.CRITICAL_RANGE_LOW        , base.CRITICAL_RANGE_HIGH        , base.IS_RESULT_ABNORMAL RESULT_ABNORMAL_FLG        , base.ACCESSION_NBR ACCESSION_NBR        , base.RESULT_STATUS 	   , base.LOINC        , base.SOURCE_SYSTEM        , CURRENT_DATETIME("America/Chicago") CREATE_TS        , base.CREATE_UID        , CURRENT_DATETIME("America/Chicago") UPDATE_TS        , base.UPDATE_UID        , base.HEALTH_SYSTEM_SOURCE_ID||\'~\'||base.ORDER_ID||\'~\'||base.EVENT_CD  UNIQUE_ID 	    	   , (CASE WHEN FACT_LABORATORY_TEMP_AMENDED1.event_id IS NOT NULL THEN 1 else 0 end ) amended_flg 	   , cast(null as INT64) LAB_PANEL_FLG 	   , -99 DIM_LAB_LOCATION_SK 	   , null CPT   FROM    (select * FROM thcdnadevdata.idm.base_clinical_result  base   where upper(base.RESULT_FLOWSHEET) = \'LABORATORY\'   and base.source_system = \'DMC_CERNER\')   base   inner JOIN thcdnadevdata.idm.dim_facility fac   On base.dim_facility_sk = fac.dim_facility_sk left outer join (select distinct HEALTH_SYSTEM_SOURCE_ID,ORDER_ID,ORIG_ORDER_DT_TM FROM thcdnadevdata.cerner_ods.dmc_orders_hist) ORDERS  ON base.HEALTH_SYSTEM_SOURCE_ID = ORDERS.HEALTH_SYSTEM_SOURCE_ID  AND base.ORDER_ID = ORDERS.ORDER_ID left outer join ( select substr(hisordernumber,1,case when instr(hisordernumber,\'-\',1,1) = 0 then 999 else instr(hisordernumber,\'-\',1,1) end -1) order_id ,max(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\',FORMAT_DATETIME(\'%Y-%m-%d\',resultdateodbc)||\' \'||resulttimeodbc)) result_ts ,max(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\',FORMAT_DATETIME(\'%Y-%m-%d\',collectdateodbc)||\' \'||collecttimeodbc)) collect_ts ,max(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\',FORMAT_DATETIME(\'%Y-%m-%d\',receivedateodbc)||\' \'||receivetimeodbc)) receive_ts ,max(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\',FORMAT_DATETIME(\'%Y-%m-%d\',orderdateodbc)||\' \'||ordertimeodbc)) order_ts ,max(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\',FORMAT_DATETIME(\'%Y-%m-%d\',admitdateodbc)||\' 00:00:00\')) admit_ts ,max(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\',FORMAT_DATETIME(\'%Y-%m-%d\',dischdateodbc)||\' 00:00:00\')) disch_ts ,max(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\',FORMAT_DATETIME(\'%Y-%m-%d\',visitstartdateodbc)||\' 00:00:00\')) visit_start_ts FROM thcdnadevdata.cerner_ods.sunquest_u_dmc_reverse_glres where 1 =  1 and hisordernumber is not null and hisordernumber not like \'G%\' and hisordernumber not like \'M%\' and hisordernumber not like \'J%\' and hisordernumber not like \'B%\' and hisordernumber not like \'D%\' and hisordernumber not like \'F%\' and hisordernumber not like \'E%\' and hisordernumber not like \'C%\' and hisordernumber not like \'A%\' and ( hisordernumber like    \'0%\' or hisordernumber like \'1%\' or hisordernumber like \'2%\' or hisordernumber like \'3%\' or hisordernumber like \'4%\' or hisordernumber like \'5%\' or hisordernumber like \'6%\' or hisordernumber like \'7%\' or hisordernumber like \'8%\' or hisordernumber like \'9%\' ) group by 1 ) SUNQUEST_U_DMC_REVERSE_GLRES on CAST(SUNQUEST_U_DMC_REVERSE_GLRES.order_id AS INT64 )= base.ORDER_ID  left outer JOIN thcdnadevdata.idm.fact_laboratory_temp_amended1 on ( 1 =  1 and base.health_system_source_id = FACT_LABORATORY_TEMP_AMENDED1.health_system_source_id and base.event_id = FACT_LABORATORY_TEMP_AMENDED1.event_id ) ) ',V_PROC_NAME,V_LOG_TABLE,V_RESULT); 
-- if v_result <> 'P' then RAISE USING message = V_RESULT; end if;
  CALL `thcdnadevdata.idm.execute_sql`('DROP TABLE IF EXISTS thcdnadevdata.idm.CERNER_BASE ',V_PROC_NAME,V_LOG_TABLE,V_RESULT);

  CALL `thcdnadevdata.idm.execute_sql`('CREATE OR REPLACE TABLE idm.CERNER_BASE CLUSTER BY HEALTH_SYSTEM_SOURCE_ID,ORDER_ID,EVENT_ID AS select base.*,fac.TM_ZONE_NM,fac.DST_IND from (SELECT * FROM idm.base_clinical_result base WHERE UPPER(base.RESULT_FLOWSHEET) = \'LABORATORY\' AND base.source_system = \'CERNER\') base INNER JOIN idm.dim_facility fac ON base.dim_facility_sk = fac.dim_facility_sk ',V_PROC_NAME,V_LOG_TABLE,V_RESULT); 
  if v_result <> 'P' then RAISE USING message = V_RESULT; end if;

  CALL `thcdnadevdata.idm.execute_sql`('CREATE OR REPLACE TABLE idm.CERNER_ORDERS CLUSTER BY HEALTH_SYSTEM_SOURCE_ID,ORDER_ID AS (SELECT ORDERS.HEALTH_SYSTEM_SOURCE_ID, ORDERS.ORDER_ID, ORDERS.ORIG_ORDER_DT_TM, ORDER_CONTAINER_R.CONTAINER_ID, CONTAINER.DRAWN_DT_TM, CONTAINER.RECEIVED_DT_TM FROM idm.fact_order_temp_order ORDERS INNER JOIN cerner_ods.cerner_order_container_r_hist ORDER_CONTAINER_R ON ORDERS.HEALTH_SYSTEM_SOURCE_ID = ORDER_CONTAINER_R.HEALTH_SYSTEM_SOURCE_ID AND ORDERS.ORDER_ID = ORDER_CONTAINER_R.ORDER_ID LEFT OUTER JOIN cerner_ods.cerner_container_hist CONTAINER ON ORDER_CONTAINER_R.HEALTH_SYSTEM_SOURCE_ID = CONTAINER.HEALTH_SYSTEM_SOURCE_ID AND ORDER_CONTAINER_R.CONTAINER_ID = CONTAINER.CONTAINER_ID WHERE COLLECTION_STATUS_FLAG=1) ',V_PROC_NAME,V_LOG_TABLE,V_RESULT); 
  if v_result <> 'P' then RAISE USING message = V_RESULT; end if;

  --added for collection_priority, report_priority, order_prioriry - Johnanthony 11/20/2025
CREATE OR REPLACE TABLE idm.CERNER_ORDERS_PRIORITY
CLUSTER BY HEALTH_SYSTEM_SOURCE_ID, ORDER_ID AS (
  WITH
    filtered_orders AS (
      -- Filter the main source table once. This corresponds to the original S04 stage.
      SELECT
        HEALTH_SYSTEM_SOURCE_ID,
        ORDER_ID,
        OE_FIELD_MEANING,
        OE_FIELD_VALUE
      FROM
        cerner_ods.cerner_order_detail_hist
      WHERE
        OE_FIELD_MEANING IN ('COLLPRI', 'REPPRI', 'PRIORITY', 'RXPRIORITY')
    )
  SELECT
    orders.HEALTH_SYSTEM_SOURCE_ID,
    orders.ORDER_ID,
    base.facility_cd,
    -- Pivot data using conditional aggregation. This replaces three LEFT JOINs with one.
    MAX(
      CASE
        WHEN UPPER(orders.OE_FIELD_MEANING) = 'COLLPRI'
        THEN cv.DISPLAY
      END
    ) AS COLLECTION_PRIORITY,
    MAX(
      CASE
        WHEN UPPER(orders.OE_FIELD_MEANING) = 'REPPRI'
        THEN cv.DISPLAY
      END
    ) AS REPORT_PRIORITY,
    MAX(
      CASE
        WHEN UPPER(orders.OE_FIELD_MEANING) IN ('PRIORITY', 'RXPRIORITY')
        THEN cv.DISPLAY
      END
    ) AS ORDER_PRIORITY_NM
  FROM
    filtered_orders AS orders
  INNER JOIN
    idm.CERNER_BASE AS base
    ON base.health_system_source_id = orders.health_system_source_id
    AND base.order_id = orders.order_id
  LEFT JOIN
    -- Join to the code value table only once.
    cerner_ods.cerner_code_value_hist AS cv
    ON orders.HEALTH_SYSTEM_SOURCE_ID = cv.HEALTH_SYSTEM_SOURCE_ID
    AND orders.OE_FIELD_VALUE = cv.CODE_VALUE
  GROUP BY
    1, 2, 3);
  if v_result <> 'P' then RAISE USING message = V_RESULT; end if;



 -- capture the base table for from cerner_base 
CREATE TEMP TABLE CERNER_BASE_TABLE_OPTIMIZED 
    PARTITION BY DATE(ORDER_COMPLETE_TS) 
    CLUSTER BY HEALTH_SYSTEM_SOURCE_ID, ORDER_ID, EVENT_ID
as ( 
    WITH CTE as (
        select DIM_FACILITY_SK, DIM_PATIENT_SK, DIM_ORDER_SK  , DIM_ORDERING_PHYSICIAN_SK, DIM_ORDER_LOCATION_SK,
            DIM_MEASURING_UNIT_SK, DIM_RESULT_TYPE_SK, FACT_ORDER_SK FACT_ORDER_SK, PATIENT_ACCOUNT_NBR, FACILITY_CD,
            HEALTH_SYSTEM_SOURCE_ID, ORDER_ID, EVENT_ID, LOINC, DST_IND, TM_ZONE_NM, ORDER_COMPLETE_TS, RESULT_VALUE,
            NORMAL_RANGE_LOW, NORMAL_RANGE_HIGH, CRITICAL_RANGE_LOW, CRITICAL_RANGE_HIGH, IS_RESULT_ABNORMAL,
            ACCESSION_NBR, RESULT_STATUS, SOURCE_SYSTEM, CREATE_UID, UPDATE_UID, EVENT_CD,
            CAST( CASE WHEN base.DST_IND = 'Y' THEN 1 WHEN base.DST_IND = 'N' THEN 0 ELSE NULL END AS BOOLEAN) as dst_flag,        
            from  thcdnadevdata.idm.CERNER_BASE base
            )
    select *, 
            thcdnadevdata.staging.convert_timezone(ORDER_COMPLETE_TS, dst_flag, TM_ZONE_NM) AS COMPLETE_TS
        from CTE
   );


-- need to dedup the base table because there are multiple records with the same information but different fact_order_sk 
CREATE TEMP TABLE CERNER_BASE_TABLE_FOR_ORDER_ID as ( 
    SELECT HEALTH_SYSTEM_SOURCE_ID, ORDER_ID, dst_flag, ORDER_COMPLETE_TS, TM_ZONE_NM 
        FROM  CERNER_BASE_TABLE_OPTIMIZED
        group by HEALTH_SYSTEM_SOURCE_ID, ORDER_ID, dst_flag, ORDER_COMPLETE_TS, TM_ZONE_NM    
); 


-- calculating for order related timestamps and timediff 
CREATE TEMP TABLE CERNER_ORDERS_TABLE_OPTIMIZED 
    CLUSTER BY HEALTH_SYSTEM_SOURCE_ID, ORDER_ID 
as ( 
    select base.HEALTH_SYSTEM_SOURCE_ID, base.ORDER_ID,  
    thcdnadevdata.staging.convert_timezone(ORDERS.ORIG_ORDER_DT_TM, base.dst_flag, base.TM_ZONE_NM) AS ORDER_DT_TM,
    thcdnadevdata.staging.convert_timezone(ORDERS.DRAWN_DT_TM, dst_flag, base.TM_ZONE_NM) AS DRAWN_TS,
    thcdnadevdata.staging.convert_timezone(ORDERS.RECEIVED_DT_TM, dst_flag, base.TM_ZONE_NM) AS RECEIVE_TS,        
    FROM CERNER_BASE_TABLE_FOR_ORDER_ID base 
    INNER JOIN thcdnadevdata.idm.CERNER_ORDERS ORDERS
        ON base.HEALTH_SYSTEM_SOURCE_ID = ORDERS.HEALTH_SYSTEM_SOURCE_ID
        AND base.ORDER_ID = ORDERS.ORDER_ID
        ); 

DROP TABLE IF EXISTS thcdnadevdata.idm.fact_laboratory_temp1_cerner;

-- create the fact_laboratory_temp1_
CREATE OR REPLACE TABLE thcdnadevdata.idm.fact_laboratory_temp1_cerner 
CLUSTER BY DIM_PATIENT_SK AS
SELECT
      SAFE_CAST(base.DIM_FACILITY_SK AS INT64) AS DIM_FACILITY_SK,
      SAFE_CAST(base.DIM_PATIENT_SK AS INT64) AS DIM_PATIENT_SK,
      SAFE_CAST(base.DIM_ORDER_SK AS INT64) AS DIM_ORDER_SK,
      SAFE_CAST(base.DIM_ORDERING_PHYSICIAN_SK AS INT64) AS DIM_ORDERING_PHYSICIAN_SK,
      SAFE_CAST(base.DIM_ORDER_LOCATION_SK AS INT64) AS DIM_ORDER_LOCATION_SK,
      SAFE_CAST(base.DIM_MEASURING_UNIT_SK AS INT64) AS DIM_MEASURING_UNIT_SK,
      SAFE_CAST(base.DIM_RESULT_TYPE_SK AS INT64) AS DIM_RESULT_TYPE_SK,
      SAFE_CAST(base.FACT_ORDER_SK AS INT64) AS FACT_ORDER_SK,
      base.PATIENT_ACCOUNT_NBR,
      base.FACILITY_CD,
      orders.ORDER_DT_TM,
      orders.DRAWN_TS,
      orders.RECEIVE_TS,
      base.COMPLETE_TS,
      CAST(ROUND(DATETIME_DIFF(ORDERS.DRAWN_TS,ORDERS.ORDER_DT_TM,SECOND)/ 60)AS float64) ORDER_TO_DRAWN_MINUTES,
      CASE WHEN ORDERS.DRAWN_TS < ORDERS.ORDER_DT_TM  THEN  
              CAST(ROUND(DATETIME_DIFF(ORDERS.RECEIVE_TS, ORDERS.ORDER_DT_TM,SECOND)/ 60)AS float64)
          ELSE
              CAST(ROUND(DATETIME_DIFF(ORDERS.RECEIVE_TS, ORDERS.DRAWN_TS ,SECOND)/ 60)AS float64)
          END AS DRAWN_TO_RECEIVE_MINUTES,  
      CASE  WHEN  ORDERS.RECEIVE_TS < ORDERS.ORDER_DT_TM THEN  
              CAST(ROUND(DATETIME_DIFF( COMPLETE_TS, ORDERS.ORDER_DT_TM,SECOND)/ 60)AS float64)
          ELSE
              CAST(ROUND(DATETIME_DIFF(COMPLETE_TS, ORDERS.RECEIVE_TS,SECOND)/ 60)AS float64) 
          END AS RECEIVE_TO_RESULT_MINUTES,
      base.RESULT_VALUE,
      base.NORMAL_RANGE_LOW,
      base.NORMAL_RANGE_HIGH,
      base.CRITICAL_RANGE_LOW,
      base.CRITICAL_RANGE_HIGH,
      base.IS_RESULT_ABNORMAL RESULT_ABNORMAL_FLG,
      base.ACCESSION_NBR ACCESSION_NBR,
      base.RESULT_STATUS,
      PRIORITY.COLLECTION_PRIORITY,
      PRIORITY.REPORT_PRIORITY,
      PRIORITY.ORDER_PRIORITY_NM,
      base.LOINC,
      base.SOURCE_SYSTEM,
      CURRENT_DATETIME("America/Chicago") CREATE_TS,
      base.CREATE_UID,
      CURRENT_DATETIME("America/Chicago") UPDATE_TS,
      base.UPDATE_UID,
      base.HEALTH_SYSTEM_SOURCE_ID || '~' || base.ORDER_ID || '~'
        || base.EVENT_CD UNIQUE_ID,
      CASE WHEN FACT_LABORATORY_TEMP_AMENDED1.event_id IS NOT NULL THEN 1
          ELSE 0 END amended_flg,
      -- CASE WHEN lpf.fact_order_sk is not null THEN 1 ELSE 0 END LAB_PANEL_FLG,
      CAST( CASE WHEN COUNT(*) OVER (PARTITION BY base.fact_order_sk) > 1 THEN 1
          ELSE 0 END AS INT64) LAB_PANEL_FLG,
      IFNULL(charge.DIM_LAB_LOCATION_SK, -99) DIM_LAB_LOCATION_SK,
      CPT_MAP.CPT CPT , 
    FROM CERNER_BASE_TABLE_OPTIMIZED  base
    LEFT OUTER JOIN CERNER_ORDERS_TABLE_OPTIMIZED  ORDERS
      ON base.HEALTH_SYSTEM_SOURCE_ID = ORDERS.HEALTH_SYSTEM_SOURCE_ID
        AND base.ORDER_ID = ORDERS.ORDER_ID
    LEFT OUTER JOIN thcdnadevdata.idm.fact_laboratory_lab_location charge
      ON ( base.health_system_source_id = charge.health_system_source_id
        AND base.order_id = charge.order_id)
    LEFT OUTER JOIN thcdnadevdata.idm.fact_laboratory_temp_amended1
      ON ( base.health_system_source_id
          = FACT_LABORATORY_TEMP_AMENDED1.health_system_source_id
        AND base.event_id = FACT_LABORATORY_TEMP_AMENDED1.event_id)
    LEFT OUTER JOIN thcdnadevdata.idm.CERNER_ORDERS_PRIORITY PRIORITY
      ON base.HEALTH_SYSTEM_SOURCE_ID = PRIORITY.HEALTH_SYSTEM_SOURCE_ID
        AND base.ORDER_ID = PRIORITY.ORDER_ID
        AND base.facility_cd = PRIORITY.facility_cd
    LEFT OUTER JOIN thcdnadevdata.staging.ff_loinc_cpt_mapping CPT_MAP
      ON base.LOINC = CPT_MAP.LOINC;


CALL `thcdnadevdata.idm.execute_sql`('DROP TABLE IF EXISTS thcdnadevdata.idm.DMC_CERNER_BASE ',V_PROC_NAME,V_LOG_TABLE,V_RESULT);


CALL `thcdnadevdata.idm.execute_sql`('CREATE OR REPLACE TABLE idm.DMC_CERNER_BASE CLUSTER BY HEALTH_SYSTEM_SOURCE_ID,ORDER_ID,EVENT_ID AS select base.*,fac.TM_ZONE_NM,fac.DST_IND from ( SELECT * FROM idm.base_clinical_result base WHERE UPPER(base.RESULT_FLOWSHEET) = \'LABORATORY\' AND base.source_system = \'DMC_CERNER\') base  INNER JOIN idm.dim_facility fac ON base.dim_facility_sk = fac.dim_facility_sk ',V_PROC_NAME,V_LOG_TABLE,V_RESULT); 
  if v_result <> 'P' then RAISE USING message = V_RESULT; end if;

CALL `thcdnadevdata.idm.execute_sql`('CREATE OR REPLACE TABLE idm.DMC_ORDERS CLUSTER BY HEALTH_SYSTEM_SOURCE_ID,ORDER_ID AS ( SELECT DISTINCT HEALTH_SYSTEM_SOURCE_ID, ORDER_ID, ORIG_ORDER_DT_TM FROM cerner_ods.dmc_orders_hist) ',V_PROC_NAME,V_LOG_TABLE,V_RESULT); 
  if v_result <> 'P' then RAISE USING message = V_RESULT; end if;

CALL `thcdnadevdata.idm.execute_sql`('CREATE OR REPLACE TABLE idm.SUNQUEST_U_DMC_REVERSE_GLRES CLUSTER BY ORDER_ID AS ( SELECT SUBSTR(hisordernumber,1,CASE WHEN INSTR(hisordernumber,\'-\',1,1) = 0 THEN 999 ELSE INSTR(hisordernumber,\'-\',1,1) END -1) order_id, MAX(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\',FORMAT_DATETIME(\'%Y-%m-%d\',resultdateodbc)||\' \'||resulttimeodbc)) result_ts, MAX(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\',FORMAT_DATETIME(\'%Y-%m-%d\',collectdateodbc)||\' \'||collecttimeodbc)) collect_ts, MAX(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\',FORMAT_DATETIME(\'%Y-%m-%d\',receivedateodbc)||\' \'||receivetimeodbc)) receive_ts, MAX(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\',FORMAT_DATETIME(\'%Y-%m-%d\',orderdateodbc)||\' \'||ordertimeodbc)) order_ts, MAX(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\',FORMAT_DATETIME(\'%Y-%m-%d\',admitdateodbc)||\' 00:00:00\')) admit_ts, MAX(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\',FORMAT_DATETIME(\'%Y-%m-%d\',dischdateodbc)||\' 00:00:00\')) disch_ts, MAX(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\',FORMAT_DATETIME(\'%Y-%m-%d\',visitstartdateodbc)||\' 00:00:00\')) visit_start_ts FROM cerner_ods.sunquest_u_dmc_reverse_glres WHERE 1 = 1 AND hisordernumber IS NOT NULL AND hisordernumber NOT LIKE \'G%\' AND hisordernumber NOT LIKE \'M%\' AND hisordernumber NOT LIKE \'J%\' AND hisordernumber NOT LIKE \'B%\' AND hisordernumber NOT LIKE \'D%\' AND hisordernumber NOT LIKE \'F%\' AND hisordernumber NOT LIKE \'E%\' AND hisordernumber NOT LIKE \'C%\' AND hisordernumber NOT LIKE \'A%\' AND ( hisordernumber LIKE \'0%\' OR hisordernumber LIKE \'1%\' OR hisordernumber LIKE \'2%\' OR hisordernumber LIKE \'3%\' OR hisordernumber LIKE \'4%\' OR hisordernumber LIKE \'5%\' OR hisordernumber LIKE \'6%\' OR hisordernumber LIKE \'7%\' OR hisor

exec_query:
-- =================================================================================================
-- Script to create and validate two temporary tables.
-- Expected Outcome: The discrepancy and duplicate detail SELECTs should return zero rows.
-- The final SELECT statement should return two summary rows with row_count = 0, confirming that
-- V_TEMP_TABLE_ORIG and V_TEMP_TABLE_OPT produce identical distinct results and V_TEMP_TABLE_OPT
-- has no duplicate rows.
-- =================================================================================================
-- 1. Stored Procedure Context

DECLARE freeze_time TIMESTAMP;


	DECLARE  pr1 DATE; 

	DECLARE out_param INT64;

	DECLARE I_PROCESS_DT STRING; 

	DECLARE V_PROCESS_DT STRING;

	DECLARE V_LOG_TABLE STRING;

	DECLARE V_START_TS DATETIME; 

	DECLARE V_END_TS DATETIME;

	DECLARE V_START_TS_TEXT STRING;

	DECLARE V_END_TS_TEXT STRING; 

	DECLARE V_PROC_NAME STRING;

	DECLARE V_RAND_NBR INT64;

	DECLARE V_ERROR_MESSAGE STRING;

	DECLARE V_SQL_START_TS DATETIME;

	DECLARE V_SQL_END_TS DATETIME; 

	DECLARE V_ROW_COUNT INT64;

	DECLARE V_SQL_START_TS_TEXT STRING;

	DECLARE V_SQL_END_TS_TEXT STRING;

	DECLARE V_SQL_LOG STRING;

	DECLARE V_LOG_TS_TEXT STRING; 

	DECLARE V_RESULT STRING;

	DECLARE V_PAREMETER_LIST STRING;

	DECLARE V_CNT INT64;

	SET I_PROCESS_DT = FORMAT_DATE('%Y-%m-%d',pr1);

	SET V_START_TS = CURRENT_DATETIME("America/Chicago"); 

